import{z as s,x as i,o as e,c as d,q as o,j as r,D as a,d as n,s as t,S as l,b as A}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"宏观发布事件","description":"","frontmatter":{"title":"宏观发布事件","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/ed-macro-release-event.md","filePath":"quant/ed-macro-release-event.md","lastUpdated":1791063341000}'),p={name:"quant/ed-macro-release-event.md"};function m(D,E,F,u,c,_){const B=i("Mermaid");return e(),d("div",null,[E[2]||(E[2]=o('<h1 id="宏观发布事件" tabindex="-1">宏观发布事件 <a class="header-anchor" href="#宏观发布事件" aria-label="Permalink to &quot;宏观发布事件&quot;">​</a></h1><div class="epigraph"><p>宏观新闻在公布后的几分钟里就基本定完价；此后市场的任务不再是发现数字，而是消化它的含义。</p><footer>—— 据 Fleming and Remolona, Journal of Finance, 1999；Andersen, Bollerslev, Diebold and Vega, Journal of Finance, 2003 整理</footer></div><p><a href="/quant/ed-opex-event">上一课</a>的载荷可由公开持仓算出；宏观发布把谱系倒过来——<strong>时点精确到秒，载荷在公布前对所有人未知</strong>。它是谱系里「确定性最高、可预测性最低」的一类：非农、CPI、GDP、央行利率决定都挂在公开日历上，数字谁也不比谁先知道。本课写发布日历、标准化意外、分钟级反应与事前的流动性摆动。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>宏观发布的事件化有三段缺口。第一，<strong>公告前的流动性撤退</strong>。做市商与限价单提交者无法预知数字方向，风险是纯双边的；他们撤单、加宽价差，把承接风险的成本变成事前的流动性洼地。只看发布后的分钟，会把事前价差算进平均成本，成交账立刻变坏。第二，<strong>公布的瞬间是跳跃，不是过程</strong>。国债市场的证据是价格在最初一两分钟基本跳完，量与价差的峰值随后才到——两者不同步，窗口不按秒分层就会被平均掉。第三，<strong>意外必须标准化</strong>。非农差 5 万人与 CPI 差 0.1 个百分点不可比；跨指标比较要除以各自的历史意外波动。</p><p><span class="marginnote">直觉类比：发洪水前，渡口船夫先把船收起来（撤单），留下的少数船坐地起价（价差加宽）。发布前 5–15 分钟的「事前窗」就是这段洪水期；回测若假设这段窗口照常成交，等于假设洪水里船照常开，成本账自然全面偏乐观。</span></p><h3 id="意外的尺度" tabindex="-1">意外的尺度 <a class="header-anchor" href="#意外的尺度" aria-label="Permalink to &quot;意外的尺度&quot;">​</a></h3> \\[S_j=\\frac{A_j-C_j}{\\sigma_{A_j-C_j}}, \\]<p>\\(A_j\\) 为实际值，\\(C_j\\) 为发布前一致预期，\\(\\sigma_{A_j-C_j}\\) 为该指标历史意外的滚动标准差，是债券市场实证的标准口径（Balduzzi、Elton 与 Green，2001）。用它才有「这次意外多大」的公共答案；原始差值让每个指标活在自己的单位里。</p><p><span class="marginnote">Croushore 与 Stark（2001）的实时数据口径：GDP 首次公布与多年后的修订值可以差出整整一个百分点；用修订值回测公告反应，等于用市场从未见过的数字。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>日历到秒，数据用实时口径。</strong> 事件表的 \\(T\\) 用发布机构的实际时间戳，不是计划的整点；\\(X\\) 与 \\(E\\) 取发布时刻可得的数据（首次公布值、发布前预期），修订值只用于长窗研究并单独标注。不这么做会错在哪：一半以上的「公告后异象」换实时口径后消失，剩下的才是市场真正定价过的东西。</p><p><strong>窗口三段。</strong> 事前窗（发布前 5–15 分钟）测撤退：价差、深度、撤单率；发布窗（最初 1–2 分钟）测价格发现完成速度；恢复窗（其后半小时到数小时）测波动与价差回落。三段对无发布日的同时段做对照，日内季节性才不会冒充事件效应。</p><p><strong>交易面分两条线。</strong> 体制线不赌数字方向，交易发布后波动与价差的体制切换——期权定价在公告前已含溢价，公布后的回吐路径就是交易对象。溢价线：股票在发布日的平均收益系统性更高（Savor 与 Wilson，2013），把持有期对准发布日是被付费承担的公告风险。两条线的风险预算不同，不能混账。</p><p><span class="marginnote">数字实例：非农实际 18.0 万、预期 20.0 万，差 −2 万；该指标历史意外的滚动标准差若为 5 万，则 \\(S=-0.4\\)，温和意外。CPI 实际 0.4%、预期 0.3%、历史意外波动 0.1 个百分点，则 \\(S=+1.0\\)。除以各自的 \\(\\sigma\\) 后，两个单位不同的指标才能放进同一张表排序。</span></p>',15)),(e(),r(l,null,{default:a(()=>[t(B,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20CAL%5B%22%E5%8F%91%E5%B8%83%E6%97%A5%E5%8E%86%EF%BC%9A%E7%B2%BE%E7%A1%AE%E5%88%B0%E7%A7%92%22%5D%20--%3E%20PRE%5B%22%E4%BA%8B%E5%89%8D%E7%AA%97%EF%BC%9A%E6%92%A4%E5%8D%95%E5%8A%A0%E5%AE%BD%E4%BB%B7%E5%B7%AE%22%5D%0A%20%20PRE%20--%3E%20DROP%5B%22%E6%95%B0%E5%AD%97%E8%90%BD%E5%9C%B0%EF%BC%9A%E6%A0%87%E5%87%86%E5%8C%96%E6%84%8F%E5%A4%96%20S%22%5D%0A%20%20DROP%20--%3E%20JUMP%5B%22%E5%8F%91%E5%B8%83%E7%AA%97%EF%BC%9A%E4%B8%80%E4%B8%A4%E5%88%86%E9%92%9F%E8%B7%B3%E5%AE%8C%22%5D%0A%20%20JUMP%20--%3E%20RECOV%5B%22%E6%81%A2%E5%A4%8D%E7%AA%97%EF%BC%9A%E9%87%8F%E4%B8%8E%E4%BB%B7%E5%B7%AE%E5%9B%9E%E8%90%BD%22%5D%0A%20%20RECOV%20--%3E%20REG%5B%22%E4%BD%93%E5%88%B6%E5%88%87%E6%8D%A2%EF%BC%9A%E6%BA%A2%E4%BB%B7%E7%9A%84%E5%9B%9E%E5%90%90%E8%B7%AF%E5%BE%84%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[n(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A("h2",{id:"机制",tabindex:"-1"},[n("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=A("p",null,"宏观发布定价为什么快：它是对称信息事件——所有人同一毫秒听到同一个数字，没有谁更知情，竞争全压在解释与速度上。与财报对照：财报前少数人可能更知情（边界由监管划出），宏观前人人同样无知，事前价差是双边风险的对等补偿，而非逆向选择补偿。Ederington 与 Lee（1993）的经典结论：价格发现集中在极短窗口，时点与意外大小解释了绝大部分波动，其余「消息」几乎不留痕迹。",-1)),(e(),r(l,null,{default:a(()=>[t(B,{id:"mermaid-48",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E4%BB%B7%E5%B7%AE%E4%B8%BA%E4%BB%80%E4%B9%88%E5%AE%BD%3F%20%E7%9C%8B%E4%BF%A1%E6%81%AF%E5%AF%B9%E7%A7%B0%E6%80%A7%22%5D%0A%20%20MAC%5B%22%E5%AE%8F%E8%A7%82%E5%8F%91%E5%B8%83%3A%20%E5%AF%B9%E7%A7%B0%E4%BF%A1%E6%81%AF%22%5D%20--%3E%20M1%5B%22%E4%BA%BA%E4%BA%BA%E5%90%8C%E4%B8%80%E6%AF%AB%E7%A7%92%E7%9F%A5%E9%81%93%E6%95%B0%E5%AD%97%22%5D%0A%20%20M1%20--%3E%20M2%5B%22%E4%BA%8B%E5%89%8D%E4%BB%B7%E5%B7%AE%20%3D%20%E5%8F%8C%E8%BE%B9%E9%A3%8E%E9%99%A9%E7%9A%84%E5%AF%B9%E7%AD%89%E8%A1%A5%E5%81%BF%22%5D%0A%20%20EAR%5B%22%E8%B4%A2%E6%8A%A5%3A%20%E5%8F%AF%E8%83%BD%E9%9D%9E%E5%AF%B9%E7%A7%B0%22%5D%20--%3E%20E1%5B%22%E5%B0%91%E6%95%B0%E4%BA%BA%E4%BA%8B%E5%89%8D%E5%8F%AF%E8%83%BD%E6%9B%B4%E7%9F%A5%E6%83%85%22%5D%0A%20%20E1%20--%3E%20E2%5B%22%E4%BB%B7%E5%B7%AE%E5%90%AB%E9%80%86%E5%90%91%E9%80%89%E6%8B%A9%E8%A1%A5%E5%81%BF%3A%20%E4%B8%8E%E7%9F%A5%E6%83%85%E8%80%85%E6%88%90%E4%BA%A4%E4%BC%9A%E4%BA%8F%22%5D%0A%20%20M2%20--%3E%20USE%5B%22%E8%AF%BB%E5%8F%82%E6%95%B0%3A%20%E4%BA%8B%E5%89%8D%E7%AA%97%E6%92%A4%E9%80%80%E6%88%90%E6%9C%AC%E5%8D%95%E5%88%97%22%5D%0A%20%20E2%20--%3E%20USE%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[n(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=o('<p>事前摆动为什么单独记账：撤单是理性避险，同一笔成交在事前窗与恢复窗的成本相差数倍；策略若只在事前窗进出（发布前平仓、发布后接回），付的就是这份避险溢价。把分钟级反应测干净的协议见<a href="/quant/obd-eventstudy-micro">事件研究的微观版本</a>。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>指标间冲击不对称：就业与通胀对利率资产是巨浪，零售与库存是涟漪；把所有发布当一个「事件池」会稀释真正定价的少数。跨市场复用要重校准：发布时点、开盘机制与做市结构不同，回吐形状不同。意外很大时反应曲线变平（市场转向质疑数据质量与修正），线性外推在高分位失效。分钟级体制交易的容量与成本在微观定价，日频回测给不出可实现收益；公告溢价要用长样本与发布日加权来算，小样本月度对比信不过。</p><p><span class="marginnote">常见误区：把所有宏观发布倒进一个「事件池」取平均。巨浪被涟漪稀释后，会得出「宏观发布没多少反应」的错误结论；正确做法是按指标分池，只对就业、通胀这类高冲击发布单独记账。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>宏观发布是时点确定、载荷未知的事件；意外经标准化才可跨指标比较。</li><li>事前窗流动性撤退、发布窗一两分钟内价格跳完、恢复窗量价回落，三段分账。</li><li>回测与事件表必须用实时口径，修订值会让公告反应变成幻象。</li><li>交易分体制线与溢价线：一个赚波动回吐，一个被付费承担公告风险。</li><li>出处：Ederington and Lee, <em>Journal of Finance</em>, 1993；Fleming and Remolona, <em>Journal of Finance</em>, 1999；Balduzzi, Elton and Green, <em>Review of Financial Studies</em>, 2001；Savor and Wilson, <em>Journal of Financial Economics</em>, 2013。</li></ul>',6))])}const f=s(p,[["render",m]]);export{C as __pageData,f as default};
